import type { RadioGroupProps, RadioGroupItemProps } from "./radio-group.types";

import * as RadixRadioGroup from "@radix-ui/react-radio-group";
import { useUniqueId } from "@system";
import React, { forwardRef, useCallback } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { RadioGroupClasses, StyledRadioGroup } from "./radio-group.styles";

const RadioGroupRoot = forwardRef<HTMLDivElement, RadioGroupProps>(
  (
    {
      className,
      defaultValue,
      value,
      onValueChange,
      variant = "default",
      required = false,
      disabled = false,
      orientation = "vertical",
      size = "default",
      children,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(RadioGroupClasses.root, className, {
      [RadioGroupClasses.sm]: size === "sm",
    });

    const handleValueChange = useCallback(
      (newValue: string) => {
        onValueChange?.(newValue);
      },
      [onValueChange],
    );

    return (
      <StyledRadioGroup
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        defaultValue={defaultValue}
        disabled={disabled}
        orientation={orientation}
        required={required}
        variant={variant}
        {...props}
        aria-required={required ? "true" : "false"}
        value={value}
        onValueChange={handleValueChange}
      >
        {React.Children.map(children, (child) => {
          if (!React.isValidElement<RadioGroupItemProps>(child)) {
            return null;
          }
          return React.cloneElement(child, {
            disabled: disabled || child.props.disabled || undefined,
          });
        })}
      </StyledRadioGroup>
    );
  },
);
RadioGroupRoot.displayName = "RadioGroup";

const Item = forwardRef<
  HTMLButtonElement,
  RadioGroupItemProps & RadixRadioGroup.RadioGroupItemProps
>(({ className, disabled, label, ...props }, ref) => {
  const uniqueId = useUniqueId("radio-group-item");
  const id = props.id ?? uniqueId;
  return (
    <div className={clsx(RadioGroupClasses.itemWrapper)}>
      <RadixRadioGroup.Item
        ref={ref}
        className={clsx(RadioGroupClasses.item, className)}
        role="radio"
        {...props}
        disabled={disabled}
        id={id}
      >
        <RadixRadioGroup.Indicator className={RadioGroupClasses.indicator} />
      </RadixRadioGroup.Item>
      {
        <label className={RadioGroupClasses.itemLabel} data-disabled={disabled} htmlFor={id}>
          {label}
        </label>
      }
    </div>
  );
});
Item.displayName = "RadioGroup.Item";

const RadioGroup = Object.assign(RadioGroupRoot, {
  Item,
});

export default RadioGroup;
